SELECT *, LAG(unit_price) OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS prev_unit_price, LAG(quantity) OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS prev_quantity, LEAD(quantity) OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS next_quantity, ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY unit_price, id) AS row_seq FROM order_items WHERE product_id = 25;
